func (q *Queries) ListImportunityParticipants(ctx context.Context, importunityID int64) ([]int64, error) {
	rows, err := q.db.QueryContext(ctx, listImportunityParticipants, importunityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int64{}
	for rows.Next() {
		var user_id int64
		if err := rows.Scan(&user_id); err != nil {
			return nil, err
		}
		items = append(items, user_id)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const listMyImportunities = `-- name: ListMyImportunities :many
SELECT i.id, i.owner_id, i.title, i.description, i.goal, i.total, i.reached_at, i.status, i.created_at, i.updated_at,
       m.status AS my_status,
       m.count AS my_count,
       m.invited_by AS my_inviter
FROM importunities i
JOIN importunity_members m ON m.importunity_id = i.id
WHERE m.user_id = $1
  AND m.status <> 'declined'
ORDER BY (m.status = 'invited') DESC, i.status DESC, i.updated_at DESC
`

