const markPrayerPeoplePrayed = `-- name: MarkPrayerPeoplePrayed :execrows
UPDATE prayer_people
SET last_prayed_on = $1::date
WHERE user_id = $2
  AND id = ANY($3::bigint[])
`

type MarkPrayerPeoplePrayedParams struct {
	Day    time.Time `json:"day"`
	UserID int64     `json:"user_id"`
	Ids    []int64   `json:"ids"`
}

// A retreat prayed for them on [day]: the next retreats take the others first.
func (q *Queries) MarkPrayerPeoplePrayed(ctx context.Context, arg MarkPrayerPeoplePrayedParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, markPrayerPeoplePrayed, arg.Day, arg.UserID, pq.Array(arg.Ids))
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

